from concurrent.futures import ThreadPoolExecutor
import threading
import time

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


_real_check = check


def all_even(xs: list[int]) -> list[int]:
    """Check every element of xs in parallel using a thread pool.

    Returns the checked values in input order. If any element is bad,
    raises the Bad of the lowest-index bad element, regardless of which
    check finishes first.
    """
    if not xs:
        return []
    with ThreadPoolExecutor(max_workers=len(xs)) as pool:
        futures = [pool.submit(check, x) for x in xs]
        results: list[int] = []
        first_bad: Bad | None = None
        for f in futures:
            try:
                results.append(f.result())
            except Bad as e:
                if first_bad is None:
                    first_bad = e
    if first_bad is not None:
        raise first_bad
    return results


def test_all_even_ok() -> None:
    assert all_even([2, 4, 6]) == [2, 4, 6]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_single_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 5, 8])
    assert ei.value.n == 5


def test_all_even_lowest_index_wins() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 3, 4, 5, 7])
    assert ei.value.n == 3


def test_all_even_negative_odd() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, -3, 4])
    assert ei.value.n == -3


def test_all_even_lowest_index_not_first_finished(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """The earliest bad element is slow; a later bad one finishes first."""
    done_late = threading.Event()

    def slow_check(x: int) -> int:
        if x == 1:
            # Wait until the later bad element has already failed.
            done_late.wait(timeout=2.0)
            time.sleep(0.05)
        elif x == 3:
            done_late.set()
        return _real_check(x)

    monkeypatch.setitem(globals(), "check", slow_check)
    with pytest.raises(Bad) as ei:
        all_even([2, 1, 4, 3])
    assert ei.value.n == 1


def test_all_even_runs_in_parallel(monkeypatch: pytest.MonkeyPatch) -> None:
    """All checks must be able to run concurrently (barrier would deadlock otherwise)."""
    barrier = threading.Barrier(3, timeout=2.0)

    def barrier_check(x: int) -> int:
        barrier.wait()
        return _real_check(x)

    monkeypatch.setitem(globals(), "check", barrier_check)
    assert all_even([2, 4, 6]) == [2, 4, 6]


def test_all_even_uses_thread_pool(monkeypatch: pytest.MonkeyPatch) -> None:
    names: list[str] = []

    def recording_check(x: int) -> int:
        names.append(threading.current_thread().name)
        return _real_check(x)

    monkeypatch.setitem(globals(), "check", recording_check)
    all_even([2, 4])
    assert names
    assert all(n != threading.main_thread().name for n in names)


def test_all_even_large_input() -> None:
    xs = [2 * i for i in range(200)]
    assert all_even(xs) == xs
    xs[150] = 1
    xs[170] = 3
    with pytest.raises(Bad) as ei:
        all_even(xs)
    assert ei.value.n == 1

